import functools

def _parse(v):
    core = v.split('+', 1)[0]
    if '-' in core:
        main, pre = core.split('-', 1)
    else:
        main, pre = core, None
    major, minor, patch = (int(x) for x in main.split('.'))
    pre_ids = pre.split('.') if pre is not None else None
    return (major, minor, patch, pre_ids)

def _cmp_id(a, b):
    a_num = a.isdigit()
    b_num = b.isdigit()
    if a_num and b_num:
        na, nb = int(a), int(b)
        return (na > nb) - (na < nb)
    if a_num and not b_num:
        return -1
    if not a_num and b_num:
        return 1
    return (a > b) - (a < b)

def _compare(v1, v2):
    m1, n1, p1, pre1 = _parse(v1)
    m2, n2, p2, pre2 = _parse(v2)
    if m1 != m2:
        return -1 if m1 < m2 else 1
    if n1 != n2:
        return -1 if n1 < n2 else 1
    if p1 != p2:
        return -1 if p1 < p2 else 1
    if pre1 is None and pre2 is None:
        return 0
    if pre1 is None and pre2 is not None:
        return 1
    if pre1 is not None and pre2 is None:
        return -1
    for a, b in zip(pre1, pre2):
        c = _cmp_id(a, b)
        if c != 0:
            return c
    if len(pre1) != len(pre2):
        return -1 if len(pre1) < len(pre2) else 1
    return 0

def semver_sort(versions):
    return sorted(versions, key=functools.cmp_to_key(_compare))

